package com.hbm.missile.completion.volcano;
import com.hbm.missile.completion.MissileContent;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
public record VolcanoSmokeEffects(double x,double y,double z) implements CustomPacketPayload {
 public static final Type<VolcanoSmokeEffects> TYPE=new Type<>(MissileContent.id("volcano_smoke"));public static final StreamCodec<RegistryFriendlyByteBuf,VolcanoSmokeEffects> CODEC=StreamCodec.of((b,p)->{b.writeDouble(p.x);b.writeDouble(p.y);b.writeDouble(p.z);},b->new VolcanoSmokeEffects(b.readDouble(),b.readDouble(),b.readDouble()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent event){event.registrar("1").playToClient(TYPE,CODEC,(packet,context)->context.enqueueWork(()->com.hbm.client.missile.completion.MissileClientEffects.volcano(packet)));}public static void send(ServerLevel level,double x,double y,double z){var packet=new VolcanoSmokeEffects(x,y,z);try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginPayloadGroup(level.getServer(),packet)){for(var player:level.players())if(player.distanceToSqr(x,y,z)<=250D*250D)PacketDistributor.sendToPlayer(player,packet);dispatchScope.commit();}}
}
